from mk import *
STRICT["on"] = True

def fig():
    g = Fig(560, 330, "גרף מהירות-זמן של טיל: עלייה קווית ל-180 מטר לשנייה ב-10 שניות, ואחר כך ירידה קווית שחוצה את האפס ב-100 שניות וממשיכה לערכים שליליים")
    X, Y = g.graph(70, 290, 420, 250, "t (s)", "v (m/s)", xticks=[(10, "10"), (100, "100")], yticks=[(180, "180")], xmax=200, ymin=-180, ymax=180, grid=False)
    g.plot(X, Y, [(0, 0), (10, 180), (190, -180)])
    g.guide(X, Y, 10, 180)
    return g

stem = r"טיל שוגר אנכית כלפי מעלה מפני כוכב לכת. בשלב מסוים הדלק נגמר והמנועים הפסיקו לפעול. הטיל המשיך לנוע עד שחזר אל פני הכוכב בהשפעת כוח הכובד בלבד. הגרף מתאר את מהירות הטיל כפונקציה של הזמן. ענו על השאלות בעזרת הגרף."

E(id="bagrut-1981-q1", year=1981, label="1981 שאלה 1", topic="kinematics", sub="kin-graphs", diff=3, fig=fig, stem=stem,
  parts=[
    P("א", r"כעבור כמה שניות נגמר הדלק?", num(10, "s"), ["graph", "understanding"], [
        X(r"הכיוון החיובי נקבע לפי הגרף: בתחילת התנועה הטיל עולה והמהירות חיובית, ולכן כלפי מעלה הוא הכיוון החיובי. כל עוד המנועים פועלים, הטיל מאיץ כלפי מעלה. ברגע שהדלק נגמר נשאר רק כוח הכובד, והמהירות מתחילה לקטון."),
        S(r"מחפשים בגרף את הנקודה שבה השיפוע משתנה", r"השיפוע של גרף מהירות-זמן הוא התאוצה. שינוי פתאומי בשיפוע אומר שהכוח השתנה, כלומר המנועים כבו", r"t = 10\,\text{s}"),
    ], r"$10\,\text{s}$", key=r"10 s"),
    P("ב", r"כעבור כמה שניות הגיע הטיל לגובה המרבי?", num(100, "s"), ["graph", "understanding"], [
        X(r"בגובה המרבי הטיל מפסיק לעלות ומתחיל לרדת. זה הרגע שבו המהירות מתאפסת ומחליפה סימן."),
        S(r"מחפשים בגרף את הרגע שבו המהירות אפס", r"לפני הרגע הזה המהירות חיובית והטיל עולה, ואחריו המהירות שלילית והטיל יורד", r"v(t) = 0 \;\Rightarrow\; t = 100\,\text{s}"),
    ], r"$100\,\text{s}$", key=r"100 s"),
    P("ג", r"מה הייתה תאוצת הטיל בזמן שמנועיו פעלו?", num(18, "m/s^2"), ["graph", "algebra"], [
        X(r"התאוצה היא השיפוע של גרף מהירות-זמן. בקטע הראשון הגרף הוא קו ישר, ולכן התאוצה קבועה."),
        S(r"מחשבים את השיפוע בקטע הראשון", r"השינוי במהירות חלקי משך הקטע. המהירות עלתה מאפס למאה ושמונים מטר לשנייה בעשר שניות", r"a = \frac{\Delta v}{\Delta t} = \frac{180 - 0}{10 - 0} = 18\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
    ], r"$18\,\text{m/s}^2$, כלפי מעלה", key=r"18 m/s^2"),
    P("ד", r"באיזה גובה נגמר הדלק?", num(900, "m"), ["graph", "algebra"], [
        X(r"הגובה הוא ההעתק מתחילת התנועה, וההעתק הוא השטח שמתחת לגרף מהירות-זמן."),
        S(r"השטח מתחת לגרף עד עשר שניות", r"מתחת לקטע הראשון יש משולש. הבסיס הוא משך הקטע והגובה הוא המהירות בסופו", r"h_1 = \tfrac{1}{2} \cdot 10 \cdot 180 = 900\,\text{m}"),
        C(r"בדיקה במשוואת המקום", r"תנועה ממנוחה בתאוצה קבועה. המקום ההתחלתי והמהירות ההתחלתית אפס", r"x = 0 + 0 + \tfrac{1}{2} \cdot 18 \cdot 10^2 = 900\,\text{m} \;\checkmark", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
    ], r"$900\,\text{m}$", key=r"900 m"),
    P("ה", r"לאיזה גובה מרבי הגיע הטיל?", num(9000, "m"), ["graph", "algebra"], [
        X(r"עד הגובה המרבי הטיל רק עולה, כלומר המהירות חיובית מאפס עד מאה שניות. הגובה הוא השטח שמתחת לגרף בכל הקטע הזה."),
        S(r"השטח מתחת לגרף עד מאה שניות", r"מעל ציר הזמן נוצר משולש אחד. הבסיס הוא מאה שניות והגובה הוא המהירות המרבית", r"H = \tfrac{1}{2} \cdot 100 \cdot 180 = 9000\,\text{m} = 9\,\text{km}"),
    ], r"$9000\,\text{m} = 9\,\text{km}$", key=r"9 km"),
    P("ו", r"כמה זמן בסך הכול נמשכה תנועת הטיל, מהשיגור עד שחזר אל פני הכוכב?", num(194.868, "s"), ["graph", "principle", "algebra"], [
        X(r"אחרי מאה שניות הטיל נופל ממנוחה מהגובה המרבי, בתאוצת הנפילה של הכוכב. את התאוצה הזאת מוצאים מהשיפוע של הקטע השני בגרף."),
        S(r"תאוצת הנפילה בכוכב", r"אחרי כיבוי המנועים פועל רק כוח הכובד, ולכן השיפוע בקטע השני הוא תאוצת הנפילה. הסימן שלילי: התאוצה כלפי מטה", r"g' = \frac{0 - 180}{100 - 10} = -2\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"משוואת המקום לירידה", r"שמים את הראשית בפני הכוכב, כלפי מעלה חיובי. הירידה מתחילה בגובה המרבי, במהירות אפס, ומסתיימת כשהגובה אפס. במקום התאוצה מציבים את תאוצת הנפילה של הכוכב, כי בירידה פועל רק כוח הכובד", r"0 = 9000 + 0 \cdot t_2 + \tfrac{1}{2}(-2)\,t_2^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מפשטים", r"חצי כפול מינוס שתיים הוא מינוס אחת. מעבירים את האיבר עם הזמן לאגף השני", r"t_2^2 = 9000"),
        S(r"מוציאים שורש", r"זמן הוא חיובי, ולכן לוקחים את השורש החיובי", r"t_2 = \sqrt{9000} \approx 94.87\,\text{s}"),
        S(r"מחברים לזמן העלייה", r"התנועה כולה היא מאה שניות עד השיא ועוד זמן הירידה", r"t = 100 + 94.87 \approx 195\,\text{s}"),
    ], r"$\approx 195\,\text{s}$", key=r"≈195 s"),
    P("ז", r"באיזו מהירות פגע הטיל בפני הכוכב?", num(189.737, "m/s"), ["principle", "algebra"], [
        X(r"הטיל יורד ממנוחה בתאוצת הנפילה של הכוכב, במשך זמן הירידה שמצאנו בסעיף הקודם."),
        S(r"משוואת המהירות לירידה", r"המהירות ההתחלתית בשיא אפס. במקום התאוצה מציבים את תאוצת הנפילה של הכוכב", r"v = 0 + (-2) \cdot 94.87 \approx -190\,\text{m/s}", eq=r"v = v_0 + at"),
        S(r"גודל המהירות", r"הסימן השלילי אומר שהטיל נע כלפי מטה. שואלים על גודל המהירות", r"|v| \approx 190\,\text{m/s}"),
        C(r"בדיקה בדרך אחרת, בלי זמן", r"משוואה שלא תלויה בזמן. ההעתק בירידה הוא מינוס הגובה המרבי", r"v^2 = 0 + 2(-2)(0 - 9000) = 36000 \;\Rightarrow\; |v| \approx 189.7 \;\checkmark", eq=r"v^2 = v_0^2 + 2a(x - x_0)"),
    ], r"$\approx 190\,\text{m/s}$, כלפי מטה", key=r"≈190 m/s"),
  ],
  concepts=["גרף מהירות-זמן", "שיפוע כתאוצה", "שטח כהעתק", "גובה מרבי כשהמהירות אפס", "נפילה חופשית בכוכב אחר"],
  summary=r"טיל עם מנוע ואחר כך בלי מנוע: קריאת זמנים מגרף, תאוצה משיפוע, גובה משטח, ונפילה בתאוצת הכובד של כוכב אחר.",
  note=r"נקודת השיא היא הרגע שבו המהירות אפס, ולא הרגע שבו המנוע כבה. אחרי הכיבוי הטיל עוד ממשיך לעלות.",
  review="הנחה שלי.\nבמקור הסעיף האחרון בלי אות. סימנתי אותו ז.\nמה לבדוק: רק לאשר.")
